import currency
I = importlib
__S = Hash(default_value='', contract='con_pixel_whale_master_v1', name='S')
__balances = Hash(default_value=0, contract='con_pixel_whale_master_v1',
    name='balances')
__metadata = Hash(default_value=0, contract='con_pixel_whale_master_v1',
    name='metadata')


def ____():
    __S['thing_info_contract'] = 'con_pixel_whale_info_v1'
    __metadata['operator'] = ctx.caller
    __metadata['things_name'] = 'Pixel Whales v1'
    __metadata['things_description'
        ] = 'On-chain Pixel Animations you can BUY and SELL!'


@__export('con_pixel_whale_master_v1')
def change_metadata(key: str, value: Any):
    assert ctx.caller == __metadata['operator'
        ], 'Only operator can set metadata!'
    __metadata[key] = value


@__export('con_pixel_whale_master_v1')
def create_thing(thing_string: str, name: str, description: str, meta: dict={}
    ):
    thing_info = I.import_module(__S['thing_info_contract'])
    sender = ctx.caller
    thing_uid = thing_info.add_thing(thing_string, name, description, meta,
        sender)
    __add_to_balance(sender)
    return thing_uid


@__export('con_pixel_whale_master_v1')
def buy_thing(uid: str):
    thing_info = I.import_module(__S['thing_info_contract'])
    sender = ctx.caller
    owner = thing_info.get_owner(uid)
    creator = thing_info.get_creator(uid)
    __assert_already_owned(uid, sender)
    price_amount = thing_info.get_price_amount(uid)
    royalty_percent = thing_info.get_royalty_amount(uid)
    assert price_amount, uid + ' is not for sale'
    assert price_amount > 0, uid + ' is not for sale'
    price_hold = thing_info.get_price_hold(uid)
    if price_hold != '':
        assert sender == price_hold, uid + ' is being held for ' + price_hold
    if royalty_percent > 0:
        royalty_amount = price_amount * (royalty_percent / 100)
        net_amount = price_amount - royalty_amount
        currency.transfer_from(royalty_amount, creator, sender)
    else:
        net_amount = price_amount
    currency.transfer_from(net_amount, owner, sender)
    __transfer_ownership(uid, sender)


@__export('con_pixel_whale_master_v1')
def sell_thing(uid: str, amount: float):
    __assert_ownership(uid, ctx.caller)
    thing_info = I.import_module(__S['thing_info_contract'])
    thing_info.set_price(uid, amount, '')


@__export('con_pixel_whale_master_v1')
def sell_thing_to(uid: str, amount: float, hold: str):
    __assert_ownership(uid, ctx.caller)
    thing_info = I.import_module(__S['thing_info_contract'])
    thing_info.set_price(uid, amount, hold)


@__export('con_pixel_whale_master_v1')
def transfer(uid: str, new_owner: str):
    sender = ctx.caller
    __assert_ownership(uid, sender)
    __assert_already_owned(uid, new_owner)
    __transfer_ownership(uid, new_owner)


@__export('con_pixel_whale_master_v1')
def approve(uid: str, to: str):
    sender = ctx.caller
    __assert_ownership(uid, sender)
    __balances[sender, uid, to] = True


@__export('con_pixel_whale_master_v1')
def revoke(uid: str, to: str):
    __balances[ctx.caller, uid, to] = None


@__export('con_pixel_whale_master_v1')
def transfer_from(uid: str, to: str, main_account: str):
    sender = ctx.caller
    assert __balances[main_account, uid, sender
        ], "You have not been given approval to transfer this user's item."
    __assert_ownership(uid, main_account)
    __assert_already_owned(uid, to)
    __transfer_ownership(uid, to)
    __balances[main_account, uid, sender] = None


@__export('con_pixel_whale_master_v1')
def like_thing(uid: str):
    sender = ctx.caller
    assert __S['liked', uid, sender] == '', sender + ' already liked ' + uid
    thing_info = I.import_module(__S['thing_info_contract'])
    thing_info.like_thing(uid)
    __S['liked', uid, sender] = True


@__export('con_pixel_whale_master_v1')
def prove_ownership(uid: str, code: str):
    sender = ctx.caller
    __assert_ownership(uid, sender)
    thing_info = I.import_module(__S['thing_info_contract'])
    thing_info.set_proof(uid, code)


def __assert_ownership(uid: str, sender):
    thing_info = I.import_module(__S['thing_info_contract'])
    owner = thing_info.get_owner(uid)
    assert owner == sender, uid + ' not owned by ' + sender


def __assert_already_owned(uid: str, sender):
    thing_info = I.import_module(__S['thing_info_contract'])
    owner = thing_info.get_owner(uid)
    assert owner != sender, uid + ' already owned by ' + sender


def __transfer_ownership(uid: str, new_owner: str):
    thing_info = I.import_module(__S['thing_info_contract'])
    old_owner = thing_info.get_owner(uid)
    thing_info.set_owner(uid, new_owner)
    if thing_info.get_price_amount(uid) > 0:
        thing_info.set_price(uid, 0, '')
    __add_to_balance(new_owner)
    __subtract_from_balance(old_owner)


def __add_to_balance(holder: str):
    if __balances[holder] is None:
        __balances[holder] = 1
    else:
        __balances[holder] = __balances[holder] + 1


def __subtract_from_balance(holder: str):
    if __balances[holder] is None:
        __balances[holder] = 0
    else:
        __balances[holder] = __balances[holder] - 1
